package com.ryanjei.orushio.pve.http;

import com.ryanjei.orushio.pve.application.*;
import com.ryanjei.orushio.pve.domain.*;
import com.ryanjei.orushio.pve.logging.AuditSink;
import com.ryanjei.orushio.pve.map.*;
import com.ryanjei.orushio.pve.security.AuthService;
import com.sun.net.httpserver.*;
import java.io.IOException;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.time.Duration;
import java.util.*;
import java.util.concurrent.*;

public final class AdminHttpServer implements AutoCloseable {
    private static final String COOKIE="orushio_session";
    private static final Map<HttpExchange,String> REQUEST_BODIES=Collections.synchronizedMap(new WeakHashMap<>());
    private static final Map<String,Set<String>> API_METHODS=Map.ofEntries(
        Map.entry("/api/v1/auth/session",Set.of("GET")),Map.entry("/api/v1/status",Set.of("GET")),Map.entry("/api/v1/players",Set.of("GET")),Map.entry("/api/v1/players/setup-administrator",Set.of("PUT","DELETE")),Map.entry("/api/v1/players/setup-administrator/ownership",Set.of("POST")),
        Map.entry("/api/v1/server/whitelist",Set.of("GET","PUT")),Map.entry("/api/v1/server/whitelist/players",Set.of("POST","DELETE")),
        Map.entry("/api/v1/maps",Set.of("GET","DELETE")),Map.entry("/api/v1/maps/import",Set.of("POST")),Map.entry("/api/v1/maps/enabled",Set.of("PUT")),Map.entry("/api/v1/maps/next",Set.of("PUT")),
        Map.entry("/api/v1/maps/setup",Set.of("GET")),Map.entry("/api/v1/maps/setup/start",Set.of("POST")),Map.entry("/api/v1/maps/setup/field",Set.of("PUT")),Map.entry("/api/v1/maps/setup/save",Set.of("POST")),Map.entry("/api/v1/maps/setup/discard",Set.of("POST")),
        Map.entry("/api/v1/game/current",Set.of("GET")),Map.entry("/api/v1/system/diagnostics",Set.of("GET")),Map.entry("/api/v1/game/recruiting/start",Set.of("POST")),Map.entry("/api/v1/game/recruiting/close",Set.of("POST")));
    private static final AuditSink NO_AUDIT=new AuditSink(){public void record(String t,String c,String code,String op){}public boolean healthy(){return true;}};
    private final HttpServer server; private final ExecutorService executor=Executors.newVirtualThreadPerTaskExecutor(); private final GameApplicationService games; private final ServerAdministrationService administration; private final MapAdministrationService maps; private final AuthService auth; private final Diagnostics diagnostics; private final AuditSink audit; private final boolean diagnosticMode; private final String expectedOrigin,expectedHost;
    public AdminHttpServer(InetAddress bind,int port,GameApplicationService games,ServerAdministrationService administration,AuthService auth,Diagnostics diagnostics)throws IOException{this(bind,port,games,administration,null,auth,diagnostics,NO_AUDIT,false);}
    public AdminHttpServer(InetAddress bind,int port,GameApplicationService games,ServerAdministrationService administration,AuthService auth,Diagnostics diagnostics,AuditSink audit,boolean diagnosticMode)throws IOException{this(bind,port,games,administration,null,auth,diagnostics,audit,diagnosticMode);}
    public AdminHttpServer(InetAddress bind,int port,GameApplicationService games,ServerAdministrationService administration,MapAdministrationService maps,AuthService auth,Diagnostics diagnostics,AuditSink audit,boolean diagnosticMode)throws IOException{
        if(!bind.isLoopbackAddress())throw new IllegalArgumentException("管理画面はlocalhost以外へ公開できません。");this.games=games;this.administration=administration;this.maps=maps;this.auth=auth;this.diagnostics=diagnostics;this.audit=audit;this.diagnosticMode=diagnosticMode;server=HttpServer.create(new InetSocketAddress(bind,port),0);expectedHost="127.0.0.1:"+server.getAddress().getPort();expectedOrigin="http://"+expectedHost;server.createContext("/",this::route);server.setExecutor(executor);
    }
    public void start(){server.start();} public int port(){return server.getAddress().getPort();} public String issueBootstrapToken(){return auth.issueBootstrap(Duration.ofMinutes(2));}
    private void route(HttpExchange x)throws IOException{String trace=UUID.randomUUID().toString();String operation=x.getRequestMethod()+" "+x.getRequestURI().getPath();try{addHeaders(x);String path=x.getRequestURI().getPath();if(path.equals("/auth/bootstrap")&&(x.getRequestMethod().equals("POST")||x.getRequestMethod().equals("GET"))){bootstrap(x);return;}if(!path.startsWith("/api/v1/")){asset(x,path);return;}AuthService.Session session=authenticated(x);boolean mutation=!x.getRequestMethod().equals("GET");if(mutation){validateMutation(x,session);if(diagnosticMode)throw new Problem(503,"DIAGNOSTIC_MODE","診断モードではゲーム操作を実行できません。");}enforceMethod(path,x.getRequestMethod());if(path.equals("/api/v1/players/setup-administrator/ownership")){UUID id=UUID.fromString(stringField(x,"uuid"));OnlinePlayerView player=administration.adoptSetupAdministrator(id);audit.record(trace,"ADMIN","SETUP_ADMINISTRATOR_ADOPTED",operation);ok(x,onlinePlayer(player));return;}if(path.equals("/api/v1/players/setup-administrator")){UUID id=UUID.fromString(stringField(x,"uuid"));boolean revoke=method(x,"DELETE");OnlinePlayerView player=revoke?administration.revokeSetupAdministrator(id):administration.grantSetupAdministrator(id);audit.record(trace,"ADMIN",revoke?"SETUP_ADMINISTRATOR_REVOKED":"SETUP_ADMINISTRATOR_GRANTED",operation);ok(x,onlinePlayer(player));return;}
        if(path.equals("/api/v1/auth/session")&&method(x,"GET"))ok(x,Map.of("csrfToken",session.csrf()));else if(path.equals("/api/v1/status")&&method(x,"GET"))ok(x,status());else if(path.equals("/api/v1/players")&&method(x,"GET"))ok(x,Map.of("players",onlinePlayers()));else if(path.equals("/api/v1/server/whitelist")&&x.getRequestMethod().equals("GET"))ok(x,whitelist());else if(path.equals("/api/v1/server/whitelist")&&x.getRequestMethod().equals("PUT")){boolean enabled=booleanField(x,"enabled");ok(x,Map.of("enabled",administration.setWhitelistEnabled(enabled)));}else if(path.equals("/api/v1/server/whitelist/players")&&x.getRequestMethod().equals("POST")){WhitelistEntryView entry=administration.addWhitelistedPlayer(stringField(x,"name"));ok(x,whitelistEntry(entry));}else if(path.equals("/api/v1/server/whitelist/players")&&x.getRequestMethod().equals("DELETE")){administration.removeWhitelistedPlayer(stringField(x,"name"));ok(x,Map.of("removed",true));}else if(path.equals("/api/v1/maps")&&method(x,"GET")){MapAdministrationService service=requiredMaps();ok(x,Map.of("maps",service.list().stream().map(AdminHttpServer::mapView).toList(),"fixedNextMapId",service.fixedNextMapId().orElse("")));}else if(path.equals("/api/v1/maps/import")&&method(x,"POST"))ok(x,mapView(importMap(x)));else if(path.equals("/api/v1/maps/enabled")&&method(x,"PUT"))ok(x,mapView(requiredMaps().setEnabled(stringField(x,"mapId"),booleanFieldFromBody(x,"enabled"))));else if(path.equals("/api/v1/maps/next")&&method(x,"PUT")){requiredMaps().fixNext(stringField(x,"mapId"));ok(x,Map.of("fixed",true));}else if(path.equals("/api/v1/maps")&&method(x,"DELETE")){requiredMaps().delete(stringField(x,"mapId"));ok(x,Map.of("deleted",true));}else if(path.equals("/api/v1/maps/setup")&&method(x,"GET"))ok(x,setupView(requiredMaps().setup()));else if(path.equals("/api/v1/maps/setup/start")&&method(x,"POST"))ok(x,setupView(requiredMaps().startSetup(stringField(x,"mapId"),UUID.fromString(stringFieldFromBody(x,"administrator")),required(x,"If-Game-State"))));else if(path.equals("/api/v1/maps/setup/field")&&method(x,"PUT")){requiredMaps().selectField(UUID.fromString(stringField(x,"administrator")),stringFieldFromBody(x,"field"),booleanFieldFromBody(x,"area"));ok(x,setupView(requiredMaps().setup()));}else if(path.equals("/api/v1/maps/setup/save")&&method(x,"POST"))ok(x,mapView(requiredMaps().saveSetup(required(x,"If-Session-Id"))));else if(path.equals("/api/v1/maps/setup/discard")&&method(x,"POST")){requiredMaps().discardSetup(required(x,"If-Session-Id"));ok(x,Map.of("discarded",true));}else if(path.equals("/api/v1/game/current")&&method(x,"GET"))ok(x,game(games.current()));else if(path.equals("/api/v1/system/diagnostics")&&method(x,"GET"))ok(x,diagnostics.snapshot());else if(path.equals("/api/v1/game/recruiting/start")&&method(x,"POST"))ok(x,operation(games.startRecruiting(required(x,"If-Game-State"))));else if(path.equals("/api/v1/game/recruiting/close")&&method(x,"POST"))ok(x,operation(games.closeRecruiting(required(x,"If-Session-Id"))));else throw new Problem(404,"NOT_FOUND","指定された機能はありません。");
      }catch(DomainException e){loggedError(x,trace,409,e.code(),e.getMessage(),operation);}catch(ServerAdministrationException e){int status=e.code().equals("INVALID_PLAYER_NAME")?400:e.code().equals("MINECRAFT_UNAVAILABLE")?503:409;loggedError(x,trace,status,e.code(),e.getMessage(),operation);}catch(MapIoException e){loggedError(x,trace,400,e.code(),e.getMessage(),operation);}catch(SecurityException e){loggedError(x,trace,403,"FORBIDDEN",e.getMessage(),operation);}catch(IllegalArgumentException e){loggedError(x,trace,400,"INVALID_INPUT",e.getMessage(),operation);}catch(IllegalStateException e){loggedError(x,trace,409,"MAP_STATE_CONFLICT",e.getMessage(),operation);}catch(Problem e){loggedError(x,trace,e.status,e.code,e.getMessage(),operation);}catch(Exception e){loggedError(x,trace,500,"INTERNAL_ERROR","内部エラーが発生しました。",operation);}finally{REQUEST_BODIES.remove(x);x.close();}}
    private AuthService.Session authenticated(HttpExchange x){String cookie=x.getRequestHeaders().getFirst("Cookie"),id=null;if(cookie!=null)id=Arrays.stream(cookie.split(";")).map(String::trim).filter(v->v.startsWith(COOKIE+"=")).map(v->v.substring(COOKIE.length()+1)).findFirst().orElse(null);AuthService.AuthResult r=auth.authenticateLimited(id,clientKey(x)+":session");if(r.type()==AuthService.ResultType.RATE_LIMITED)throw new Problem(429,"AUTH_RATE_LIMITED","認証試行回数が多すぎます。しばらく待ってください。");if(r.type()!=AuthService.ResultType.SUCCESS)throw new Problem(401,"AUTH_REQUIRED","認証が必要です。");return r.session();}
    private void bootstrap(HttpExchange x)throws IOException{String token=header(x,"X-Bootstrap-Token");if(token.isEmpty()&&x.getRequestURI().getRawQuery()!=null)token=Arrays.stream(x.getRequestURI().getRawQuery().split("&")).filter(v->v.startsWith("token=")).map(v->v.substring(6)).findFirst().orElse("");AuthService.AuthResult r=auth.exchangeLimited(token,clientKey(x)+":bootstrap");if(r.type()==AuthService.ResultType.RATE_LIMITED)throw new Problem(429,"AUTH_RATE_LIMITED","認証試行回数が多すぎます。しばらく待ってください。");if(r.type()!=AuthService.ResultType.SUCCESS)throw new Problem(401,"AUTH_REQUIRED","bootstrap tokenが無効です。");x.getResponseHeaders().add("Set-Cookie",COOKIE+"="+r.session().id()+"; Path=/; HttpOnly; SameSite=Strict");if(x.getRequestMethod().equals("GET")){x.getResponseHeaders().set("Location","/");x.sendResponseHeaders(303,-1);}else ok(x,Map.of("csrfToken",r.session().csrf()));}
    private void validateMutation(HttpExchange x,AuthService.Session s){if(!expectedHost.equalsIgnoreCase(header(x,"Host")))throw new Problem(403,"FORBIDDEN","Hostが許可されていません。");if(!expectedOrigin.equalsIgnoreCase(header(x,"Origin")))throw new Problem(403,"FORBIDDEN","Originが許可されていません。");if(!s.csrf().equals(header(x,"X-CSRF-Token")))throw new Problem(403,"FORBIDDEN","CSRF tokenが無効です。");}
    private Map<String,Object> status(){Map<String,Object> d=new LinkedHashMap<>(game(games.current()));d.putAll(diagnostics.snapshot());return d;}private Map<String,Object> game(GameSession s){return Map.of("gameState",s.state().name(),"sessionId",s.sessionId().toString(),"participantCount",s.participants().size(),"participantLimit",4);}private static Map<String,Object> operation(OperationResult r){return Map.of("operationId",r.operationId(),"sessionId",r.sessionId(),"state",r.state());}
    private List<Map<String,Object>> onlinePlayers(){return administration.onlinePlayers().stream().map(AdminHttpServer::onlinePlayer).toList();}
    private static Map<String,Object> onlinePlayer(OnlinePlayerView player){return Map.of("uuid",player.uuid().toString(),"name",player.name(),"setupAdministrator",player.setupAdministrator(),"administratorRevocable",player.administratorRevocable());}
    private Map<String,Object> whitelist(){return Map.of("enabled",administration.whitelistEnabled(),"players",administration.whitelistedPlayers().stream().map(AdminHttpServer::whitelistEntry).toList());}
    private static Map<String,Object> whitelistEntry(WhitelistEntryView entry){return Map.of("uuid",entry.uuid().toString(),"name",entry.name());}
    private static String stringField(HttpExchange x,String field)throws IOException{String body=requestBody(x);var matcher=java.util.regex.Pattern.compile("\\\""+java.util.regex.Pattern.quote(field)+"\\\"\\s*:\\s*\\\"([^\\\"]*)\\\"").matcher(body);if(!matcher.find())throw new Problem(400,"INVALID_INPUT",field+"が必要です。");return matcher.group(1);}private static String stringFieldFromBody(HttpExchange x,String field)throws IOException{return stringField(x,field);}
    private static boolean booleanField(HttpExchange x,String field)throws IOException{String body=requestBody(x);var matcher=java.util.regex.Pattern.compile("\\\""+java.util.regex.Pattern.quote(field)+"\\\"\\s*:\\s*(true|false)").matcher(body);if(!matcher.find())throw new Problem(400,"INVALID_INPUT",field+"が必要です。");return Boolean.parseBoolean(matcher.group(1));}private static boolean booleanFieldFromBody(HttpExchange x,String field)throws IOException{return booleanField(x,field);}private static String requestBody(HttpExchange x)throws IOException{String cached=REQUEST_BODIES.get(x);if(cached!=null)return cached;byte[] bytes=x.getRequestBody().readNBytes(65_537);if(bytes.length>65_536)throw new Problem(413,"INPUT_TOO_LARGE","入力が大きすぎます。");String body=new String(bytes,StandardCharsets.UTF_8);REQUEST_BODIES.put(x,body);return body;}
    private MapAdministrationService requiredMaps(){if(maps==null)throw new Problem(404,"NOT_FOUND","マップ管理は利用できません。");return maps;}private MapProfile importMap(HttpExchange x)throws IOException{Map<String,String> q=query(x);String id=q.getOrDefault("mapId",""),name=q.getOrDefault("displayName","");if(id.isBlank()||name.isBlank())throw new Problem(400,"INVALID_INPUT","mapIdと表示名が必要です。");java.nio.file.Path temp=java.nio.file.Files.createTempFile("orushio-map-",".zip");try{try(var out=java.nio.file.Files.newOutputStream(temp)){byte[] b=new byte[8192];long total=0;for(int n;(n=x.getRequestBody().read(b))>=0;){total+=n;if(total>SafeWorldZipImporter.DEFAULT_LIMITS.maxZipBytes())throw new Problem(413,"ZIP_SIZE","ZIPサイズが上限を超えています。");out.write(b,0,n);}}return requiredMaps().importZip(temp,id,name);}finally{java.nio.file.Files.deleteIfExists(temp);}}private static Map<String,String> query(HttpExchange x){Map<String,String> result=new HashMap<>();String raw=x.getRequestURI().getRawQuery();if(raw==null)return result;for(String part:raw.split("&")){String[] pair=part.split("=",2);if(pair.length==2)result.put(java.net.URLDecoder.decode(pair[0],StandardCharsets.UTF_8),java.net.URLDecoder.decode(pair[1],StandardCharsets.UTF_8));}return result;}private static Map<String,Object> mapView(MapProfile p){Map<String,Object> v=new LinkedHashMap<>();v.put("mapId",p.mapId().value());v.put("displayName",p.displayName());v.put("enabled",p.enabled());v.put("setupComplete",p.setupComplete());v.put("missing",p.missingRequirements().stream().map(MapFieldCatalog::label).toList());v.put("createdAt",p.createdAt().toString());return v;}private static Map<String,Object> setupView(MapAdministrationService.SetupView s){List<Map<String,Object>> fields=MapFieldCatalog.FIELDS.stream().map(field->{int count=s.counts().getOrDefault(field.key(),0);return Map.<String,Object>of("key",field.key(),"label",field.label(),"area",field.area(),"required",field.required(),"requiredCount",field.requiredCount(),"count",count,"complete",!field.required()||count>=field.requiredCount());}).toList();return Map.of("active",s.active(),"mapId",s.mapId(),"displayName",s.displayName(),"administrator",s.administrator(),"selectedField",s.selectedField(),"area",s.area(),"missing",s.missing().stream().map(MapFieldCatalog::label).toList(),"fields",fields);}
    private void loggedError(HttpExchange x,String trace,int status,String code,String message,String operation)throws IOException{audit.record(trace,"HTTP_ERROR",code,operation);error(x,status,code,message,trace);}private static String required(HttpExchange x,String name){String v=header(x,name);if(v.isBlank())throw new Problem(400,"INVALID_INPUT",name+"が必要です。");return v;}private static String clientKey(HttpExchange x){return x.getRemoteAddress().getAddress().getHostAddress();}private static String header(HttpExchange x,String n){String v=x.getRequestHeaders().getFirst(n);return v==null?"":v;}private static boolean method(HttpExchange x,String m){return x.getRequestMethod().equals(m);}
    private static void enforceMethod(String path,String method){Set<String> allowed=API_METHODS.get(path);if(allowed!=null&&!allowed.contains(method))throw new Problem(405,"METHOD_NOT_ALLOWED","このHTTPメソッドは利用できません。");}
    private void asset(HttpExchange x,String path)throws IOException{String r=switch(path){case "/","/index.html"->"/web/index.html";case "/app.js"->"/web/app.js";case "/style.css"->"/web/style.css";default->null;};if(r==null)throw new Problem(404,"NOT_FOUND","ページがありません。");try(var in=getClass().getResourceAsStream(r)){if(in==null)throw new Problem(404,"NOT_FOUND","ページがありません。");byte[] b=in.readAllBytes();x.getResponseHeaders().set("Content-Type",r.endsWith(".html")?"text/html; charset=utf-8":r.endsWith(".css")?"text/css; charset=utf-8":"text/javascript; charset=utf-8");x.sendResponseHeaders(200,b.length);x.getResponseBody().write(b);}}
    private static void ok(HttpExchange x,Object d)throws IOException{send(x,200,Json.value(Map.of("ok",true,"data",d)));}private static void error(HttpExchange x,int s,String c,String m,String t)throws IOException{send(x,s,Json.value(Map.of("ok",false,"error",Map.of("code",c,"message",m,"fields",Map.of(),"traceId",t))));}private static void send(HttpExchange x,int s,String body)throws IOException{byte[] b=body.getBytes(StandardCharsets.UTF_8);x.getResponseHeaders().set("Content-Type","application/json; charset=utf-8");x.sendResponseHeaders(s,b.length);x.getResponseBody().write(b);}private static void addHeaders(HttpExchange x){x.getResponseHeaders().set("X-Content-Type-Options","nosniff");x.getResponseHeaders().set("Content-Security-Policy","default-src 'self'; connect-src 'self'; script-src 'self'; style-src 'self'");x.getResponseHeaders().set("Cache-Control","no-store");}
    public void close(){server.stop(1);executor.shutdownNow();}private static final class Problem extends RuntimeException{final int status;final String code;Problem(int s,String c,String m){super(m);status=s;code=c;}}
}
